INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1077475-cie301', 'stk-user2728', 'CIE 301', 'info', '{"desc": "جودة المقرر بشكل عام\nجيدة جدا\n\nالمواضيع التي يغطيها المقرر\nحساب نسبة الخطأ error and relative errors\nالسقنفكانت فيقرز والفواصل العشرية والتقريب وغيرها\nإيجاد جذور الحل لمعادلات غير خطية\nنظم حل معادلات primary and ordinary differential equations\nاستخدام قوانين وفرضيات للتقريب في إيجاد بعض الحلول\nهذه المواضيع إللي أذكرها حاليا\nبشكل عام هو يتكلم عن فلسفة زائدة في حل بعض المعادلات والمسائل باستخدام نظريات وفرضيات متنوعة\nطبعا هالمعادلات والمسائل نواجهها دايم في أغلب الكورسات إللي نأخذها لكن هنا بهالكورس يحاول يعلمك كيف تتعامل معها\nومن هنا السيلابس حق المادة\nhttp://ocw.kfupm.edu.sa/BrowseCategory.aspx?did=SE&dname=Systems+Engineering&cid=SE301&oid=2539&category=Syllabus\n\nالكتاب المستخدم للمقرر\nأرى أنه مناسب ومفيد الكتاب في أي مادة\nلكن للأسف لم أطلع عليه فكان إعتمادي فقط على السلايدات في المذاكرة\nلأني أرى أن المادة ما تستاهل إني أتفرغ لها وأقعد أقرأ من الكتب فهناك مواد تخصصية ألزم منها\nفلا أستطيع الإفادة في هذا الجانب\nفقط إحتياجي للكتاب هو لحاجة وحدة وهي للرجوع لمسائل الهوموركات والبروجكت المختارة من قبل الدكتور لحلها\n\nالأسئلة والأمثلة المستخدمة في المقرر\nإذا كان من الكتاب فلا يوجد تقييم\nإذا كان من السلايدات\nأشوف أنها غير وافية وفيها غموض لا تستطيع فهمها إلا إذا بين لك الدكتور خطوة/خطوات الحل فيها\n\nمدى فائدته في الناحية التطبيقية\nله فائدة كبيرة وتطبيقية (علمية وليست عملية) ولا أحد ينكر ذلك\nلكن حاليا يوجد برامج تحل لك هذه المعادلات في ثانية وحدة فيكون هذا المقرر useless بالنسبة لهالبرامج\nما يميز هالمقرر أنه يعلمك كيف هالبرنامج حل لك هالمعادلات وحتى تعرف الأساسيات والاستنادات إللي ماشي عليها\nوأيضا يفيدك نظريا كيف علمائنا الأوائل أبدعوا عشان يحلون هالمعادلات ونظرياتهم إللي وضعوها فيها\n\nولكم الحرية في تقييم المقرر باستحداث بنود أخرى ترونها مناسبه لتقييمه.\nالكورس أشوفه رياضيات أكثر وليس هندسة\nيمكن عشان فيه جانب برمجي مال للهندسة\nالكورس تقريبا فيه 10 % بروجكت تحله باستخدام أحد هالبرامج\nStudents may use FORTRAN, MATLAB or C Language (PC or UNIX versions) or any other language to write programs to solve computer homework assignments.\nولهذا السبب صارت مواد البرمجة 101 و 102 و 103 أحد متطلبات هذه المادة\n\nأفضل وسيلة لمذاكرة هالمادة هو المتابعة مع الدكتور وتسجيل أهم الملاحظات والفرضيات في طرق الحل\nتراجع الدرس في الغرفة\nتحل مسائل من الكتاب تتعلق بهالدرس\nتحل الهومورك في وقته\nالكوزات والمياجر تسوي مراجعة للي درسته بس لازم تطبق إللي درسته بحل معادلات وتتعود عليها\nالحل والتدرب على الإجابة على المسائل والتعود عليها شيء مهم في هالمادة حتى تساعدك في تحسين مستواك في المادة وتجنب الأخطاء أثناء الإختبار\nحاولت أتذكر وهذا إللي طلعت فيه\nالمادة ما هي كومن في الاسئلة كل مدرس وطريقته\nلكن مواعيد المياجر والفاينلات كومن\nالمادة أشوفها سلف ستدي وإللي ما عنده وقت أو ماله نفس يكتفي بالسلايدات أرى إنها تمشي الوضع\nالسلايدات غالبا هي نفسها إللي يشرحون بها مدرسين هالمادة\nحاول تأخذها بعد ماث 202/260 على طول ولا تأخذها معها أو قبلها حتى لا تتلخبط لأنها هي ماث وحاول تربطهم مع بعض ولا تفصل بينهم فترة طويلة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/6", "user": "user2728", "ts": 1344376979000, "tid": 120895, "pn": 6}}', 1344376979000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1077549-cie301', 'stk-user5812', 'CIE 301', 'info', '{"desc": "حل اسئلة واولد اكزامز … تمشي فيها\nالمادة بسيطة وسلسة\n\nتحتاج فهم للكونسبت … وحل اسئلة … عشان تعود نفسك عالحل\n\nلأنه في الميجر … لو غلطت في ناتج … اللي بعده كله بيصير غلط 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/8", "user": "user5812", "ts": 1344389197000, "tid": 120895, "pn": 8}}', 1344389197000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1198574-cie301', 'stk-chemist', 'CIE 301', 'info', '{"desc": "جودة المقرر بشكل عام:\nممتازه جدا\n\nالمواضيع التي يغطيها المقرر:\nبختصار الكورس يتكلم عن شيئين فقط\n1) كيف انك تحسب المسائل اللي ماتحل تحليليا وتحلها تقريبا\n2) تحسب الأخطاء في كل طريقة تقريبية ومن هذا الخطأ تقرر أي من الطرق التي استخدمتها هي الأفضل\n\nالكتاب المستخدم للمقرر:\nممتاز جدا يعيبه بعض التفاصيل الزايده اللي ممكن انها تضيع الواحد\n\nالأسئلة والأمثلة المستخدمة في الكتاب:\nقليلة وهذا أيضا ما يعيب الكتاب في بعض الأحيان\n\nمدى فائدته في الناحية التطبيقية:\nله فائدة كبيره في حساب بعض المسائل في الهندسة الكيميائية إلا الآن استخدمت هذا الكورس في CHE 306 و CHE 402 👍\n\nنصيحة:\nالكورس هذا سهل ومن أمتع الكورسات في الجامعة صعوبته في البداية والنهاية وسهولته في الوسط لا تفوته كورس قريد\n\nوجهة نظر:\nأنا اعترض على تسمية الكورس بهذا الإسم الكورس أقرب للماث من هندسة النظم ليه مايكون إسمه مثلا Math 303 أو اسم شبيه بهذا الإسم 🤠", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/11", "user": "Chemist", "ts": 1363052756000, "tid": 120895, "pn": 11}}', 1363052756000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1233653-cie301', 'stk-cesar_peace', 'CIE 301', 'info', '{"desc": "+1\n\nالكورس سهل نوعا ما … يحتاجله ممارسة فقط على طريقة الحل وعدم ارتكاب اي خطأ أثناء الحل\nلإن الحل عبارة عن سلسلة متتابعه تغلط في جزء … ماوراء هذا الجزء راح غالبا يكون خطأ !!\n\nالمياجر والفاينل ساعة ونص فقط … بالتالي يجب أن تتدرب جيدا على استغلال وقتك أثناء الحل\n\nفالكم أحلى قريد فيها 😆 ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/17", "user": "CeSaR_PeaCe", "ts": 1370829939000, "tid": 120895, "pn": 17}}', 1370829939000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1277031-cie301', 'stk-saami', 'CIE 301', 'info', '{"desc": "طيب ي شباب الماده هذي تسبب ضغط خلال السمستر ؟\nيعني شغلها كثير من ناحية ساعات المذاكرة , هومووركات , كويزات … لأني افكر انزلها بسمستر فيه مواد دسمة 🥊\nوهل ينفع أخذها مع ماث 202 😐 ؟!\n\n…ويعطيكم العافية 🥰", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/20", "user": "saami", "ts": 1382540674000, "tid": 120895, "pn": 20}}', 1382540674000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1320713-cie301', 'stk-user4492', 'CIE 301', 'info', '{"desc": "المادة جميلة ولا تتعبون بإختيار دكتور لها إلا إذا كنت تهتم مرة للدكتور،\nيعني أهم شيء وقت المحاضرة يكون مناسب لجدولك.\nمن أسهل المواد اللي خذيتها من برى القسم وسلسة ومجرد خطوات تمشي عليها.\nكل ماحليت أكثر وتدربت أكثر على المسائل، كل ماجبت درجات أحسن،\nالجميل فيها إنها افرج سكشن وكل دكتور يحط الاختبار لطلابه. (إلا إذا طحت مع دوافير :])\nبالتوفيق ❤️", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/24", "user": "user4492", "ts": 1390086821000, "tid": 120895, "pn": 24}}', 1390086821000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1364917-cie301', 'stk-user4541', 'CIE 301', 'info', '{"desc": "بالنسبة لمادة cise301 اعتبرها اسهل واحلى مادة درستها بالجامعة …\n\nمافيها اي تعقيدات كلها تعتمد على حسابات وقوانين وخطوات حل …\n\nالكتاب ما اقدر اقيمه لاننا مانستخدمه ابد … السلايدات كافية ووافية …\n\nالمادة تحتاج الى متابعة للدكتور خلال شرح القانون وكيف يحل المسألة …\n\nالميجر والفاينل سهل جدا لما تكون متعود على حل المسائل والاولد اقزامز …\n\nمادة قريد , لانها بعيدة عن التعقيد …\n\nاعتقد انها مادة اقرب الى الماث من cise … لكن الحمد لله انها تعتبر احد مواد التخصص وترفع معدل الميجر …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/26", "user": "user4541", "ts": 1400136412000, "tid": 120895, "pn": 26}}', 1400136412000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1393825-cie301', 'stk-kemooo', 'CIE 301', 'info', '{"desc": "الكورس جدا سهل ولو جبت اقل من b بالنسبه ليا اعتبرك انسان مهمل في الدراسه …\n\nالا في حاله المدرس كان مو كويس …\n\nالـ 202 يبالها شغل وتدريب\n\nاما الـ\n\n301 يبالها تدريب بسيط\n\nموفق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/28", "user": "KeMoOo", "ts": 1409172913000, "tid": 120895, "pn": 28}}', 1409172913000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1414070-cie301', 'stk-user2352', 'CIE 301', 'info', '{"desc": "^^\nصراحة ما انصحك تنزلها مع math260 والأفضل تأخذها على طول بعد math260 من تجارب معظم الطلاب يستحسن تأخذها صيفي سهالات مع د. السيف\nإلا في حالة كان مدرسها ممتاز مثل وسيم رعد أو طارق شلظامي تقدر تأخذها مع ماث260", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/35", "user": "user2352", "ts": 1416485655000, "tid": 120895, "pn": 35}}', 1416485655000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437794-cie301', 'stk-user8581', 'CIE 301', 'info', '{"desc": "الكورس مثل ماقالوا الشباب تقريبا ماث وهو المفروض انك تستخدم شوي برمجة لكن بعض الدكاترة مايركز على هذا الشيئ فيكون الكورس كأنه ماث\n\nهو سهل لكن مايعني انك تسحب عليه …مايكفي انك تقرأ السلايدات …لازم تحل بعض الاسئلة كتدريب ( مثل اي كورس ماث )\nالحسابات اغلبها سهلة لكن طويلة ومرتبطة في بعض … لأن الكورس مب coordinated فنظام الهوموركات والمياجر يختلف من دكتور الى دكتور\nمثلا أنس وقار يعطي 7 اسئلة هومورك وحلهم طويلة خاصة في الماتيريال الي بعد الميجر الثاني اما ميسورولا يعطي سؤالين 3 بالكثير في الهومورك …\n\nبشكل عام هو كورس سهل لكن يحتاج تحل بعض الاسئلة والمياجر لو بيصعبونها يخلون حل الاسئلة طويل شوي لأنه الاسئلة ماتقدر تخلي فيها تريك … المفروض ماتطلع من الكورس بأقل من b\nوبخصوص ماث 260 او 202 صحيح ان ماتيريال الفاينل كان عن المعادلات التفاضلية لكن ما احتجتهم كثير الا لبعض الأساسيات فما اشوف لها داعي واحد يأخذ 301 على طول بعد 202 او 260\n- الكورس اتوقع انه افرج سكشن\n- مجموع درجاتي كان تقريبا 80 وطلعت بـ a\n- انصح الشباب انهم ينزلوها في الصيف مع كورس متوسط مائل للصعوبة\nهذا سلاباس الكورس لـ 151\nlink", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/39", "user": "user8581", "ts": 1451754746000, "tid": 120895, "pn": 39}}', 1451754746000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1445741-cie301', 'stk-2012_o-m-f', 'CIE 301', 'info', '{"desc": "السلام عليكم…\n\nياشباب… ناوي أنزل المادة في الصيف مع ee203\nوللأسف مضطر لان جدولي مايسمح في الأترام القادمة…\n\nالأدفايزر يقول راح تكون ثقيلة… كإنها 18 ساعة في الترم العادي…\n\nإلى أي مدي كلامه صح… وهل في أحد جربها…\nبإيش تنصحون؟", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/44", "user": "2012_O-M-F", "ts": 1459719049000, "tid": 120895, "pn": 44}}', 1459719049000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1454012-cie301', 'stk-user9534', 'CIE 301', 'info', '{"desc": "والله ما أعرفه , فيه دكاترة يتعاملون بالكورس زي الماث بحيث فقط تعرف الفكرة العامة للقانون وتمشي عليها , وفيه دكاترة ثانيين يتعاملون كأنه كورس برمجة وطول الوقت يعطيك واجبات مات لاب (MATLAB) . شوف دكتورك وش وضعه وهل يناسب لك أو لا .", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/49", "user": "user9534", "ts": 1468794106000, "tid": 120895, "pn": 49}}', 1468794106000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1454043-cie301', 'stk-maged', 'CIE 301', 'info', '{"desc": "قالنا انه فيه ١٢ واجب ٤ منها برمجة ! … سؤال ياصديقي ، المياجر والفاينل كومون بين كل السكاشن ؟\n\nقل غيره يابن الحلال 😦 … انا والله منزل الكورس أدور القريد ، انت أخذت معه 301 ؟ لأنه أشوف بموضوع التقييم الشباب يقولون اختباراته نسخ لصق من الجمعية !\nأنا ناوي معدل براسي ولازم اجيب قريد كويس بهالكورس وفضلته على انجلش٢١٤ عشان القريد >< فتنصح أكمل بالكورس ولا أدردب لأني الآن منزل ٨ ساعات زي الأسد 😀", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/51", "user": "Maged", "ts": 1468859311000, "tid": 120895, "pn": 51}}', 1468859311000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1456686-cie301', 'stk-kikm1995', 'CIE 301', 'info', '{"desc": "كورس لزيز جدا\nشخصيا أخذته مع الدكتور Mysorewala ، من افضل الدكاترة احتراما وخُلُقا والاهم شرْحًا وتعاونًا\nفي البداية كنت ما اركز كثير معاه وكنت ماخذ المادة ع انها صعبة ، جبت العيد بالميجر الاول وتحت الافرج الدرجة\nبعدها صرت اركز معاه والحمدلله طلع الكورس اسهل بكثير مما توقعت\nوفي الاخير طلعت بقريد كويس ، ولولا الميجر الاول كان ممكن اطلع بقريد افضل كمان\n\n** اتوقع الكورس افضل يكون بالصيف", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/53", "user": "KIKM1995", "ts": 1472991436000, "tid": 120895, "pn": 53}}', 1472991436000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1458426-cie301', 'stk-cs_scientist', 'CIE 301', 'info', '{"desc": "أشوف الدكتور أنس قالنا إن المياجر بتكون كومن و الدرجات ستاندرد ذا الترم\nبس الله يسمع منك و يكون كلام فاضي، لأن توزيع الدرجات مجحف صراحة و يطير القريدات بسهولة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/58", "user": "CS_Scientist", "ts": 1474532283000, "tid": 120895, "pn": 58}}', 1474532283000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1458475-cie301', 'stk-k_94', 'CIE 301', 'info', '{"desc": "^^^^^\n\nفي الصيف التوزيع كان ستاندرد ما عدا الA و الA+ …\n\nالمياجر كانت سؤالين من الدكتور وسؤال من الpool حقهم تبع الأسئلة\n\nانا كان مجموعي 90.1 تقريبا واعطاني دكتوري A", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/cie-301-numerical-methods/120895/59", "user": "K_94", "ts": 1474568508000, "tid": 120895, "pn": 59}}', 1474568508000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
